import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <int TPB>
__global__ void mean_var_kernel(const __half* __restrict__ input,
                                float* __restrict__ mean,
                                float* __restrict__ var,
                                int N, int C, int H, int W,
                                float eps) {
    // one block per channel
    const int c = blockIdx.x;
    const int stride = TPB * gridDim.y; // number of elements each thread jumps
    const int total = N * H * W;
    const int idx_base = c * total; // start of this channel

    __shared__ float shared_sum[TPB];
    __shared__ float shared_sumsq[TPB];

    float sum = 0.0f;
    float sumsq = 0.0f;

    // each thread processes multiple elements
    for (int i = threadIdx.x; i < total; i += TPB) {
        int idx = idx_base + i;
        __half h = input[idx];
        float val = __half2float(h);
        sum += val;
        sumsq += val * val;
    }

    shared_sum[threadIdx.x] = sum;
    shared_sumsq[threadIdx.x] = sumsq;
    __syncthreads();

    // reduction in shared memory
    for (int offset = TPB / 2; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) {
            shared_sum[threadIdx.x] += shared_sum[threadIdx.x + offset];
            shared_sumsq[threadIdx.x] += shared_sumsq[threadIdx.x + offset];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        float channel_sum = shared_sum[0];
        float channel_sumsq = shared_sumsq[0];
        float m = channel_sum / total;
        float v = channel_sumsq / total - m * m;
        // safeguard variance
        if (v < 0.0f) v = 0.0f;
        mean[c] = m;
        var[c] = v + eps;
    }
}

template <int TPB>
__global__ void normalize_kernel(const __half* __restrict__ input,
                                 __half* __restrict__ output,
                                 const float* __restrict__ mean,
                                 const float* __restrict__ var,
                                 int N, int C, int H, int W) {
    // one thread per element
    int idx = blockIdx.x * TPB + threadIdx.x;
    int total = N * C * H * W;
    if (idx >= total) return;

    // compute coordinates
    int w = idx % W;
    int tmp = idx / W;
    int h = tmp % H;
    tmp = tmp / H;
    int c = tmp % C;
    int n = tmp / C;

    int flat_idx = ((n * C + c) * H + h) * W + w;
    __half hval = input[flat_idx];
    float val = __half2float(hval);
    float m = mean[c];
    float inv_std = rsqrtf(var[c]); // 1 / sqrt(var+eps)
    float norm = (val - m) * inv_std; // weight = 1, bias = 0
    output[flat_idx] = __float2half(norm);
}

void batchnorm_forward(at::Tensor input, at::Tensor output) {
    const int N = input.size(0);
    const int C = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);
    const float eps = 1e-5f;

    // allocate temporary mean/var tensors
    auto options_f = at::TensorOptions().dtype(at::kFloat).device(input.device());
    at::Tensor mean = at::empty({C}, options_f);
    at::Tensor var  = at::empty({C}, options_f);

    const int TPB = 256;
    dim3 grid(C);
    dim3 block(TPB);

    // launch mean/var kernel
    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "mean_var_kernel", ([&] {
        mean_var_kernel<TPB><<<grid, block>>>(
            input.data_ptr<scalar_t>(),
            mean.data_ptr<float>(),
            var.data_ptr<float>(),
            N, C, H, W,
            eps);
    }));
    cudaGetLastError();

    // launch normalize kernel
    const int total = N * C * H * W;
    const int blocks = (total + TPB - 1) / TPB;
    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "normalize_kernel", ([&] {
        normalize_kernel<TPB><<<blocks, TPB>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            mean.data_ptr<float>(),
            var.data_ptr<float>(),
            N, C, H, W);
    }));
    cudaGetLastError();
}
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("batchnorm_forward", &batchnorm_forward, "BatchNorm forward (CUDA)");
}
'''

module = load_inline(name='batchnorm_cuda',
                     cpp_sources='',
                     cuda_sources=src,
                     functions=['batchnorm_forward'],
                     verbose=False)

class ModelNew(nn.Module):
    def __init__(self, num_features: int):
        super().__init__()
        self.num_features = num_features
        # dummy parameters to mimic nn.BatchNorm2d interface
        self.weight = nn.Parameter(torch.ones(num_features, dtype=torch.float16, device='cuda'))
        self.bias   = nn.Parameter(torch.zeros(num_features, dtype=torch.float16, device='cuda'))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda and x.dtype == torch.float16
        out = torch.empty_like(x)
        module.batchnorm_forward(x, out)
        # apply affine transform (weight and bias) – weight=1, bias=0 by default
        # we keep the same semantics as nn.BatchNorm2d (weight * out + bias)
        out = out * self.weight.view(1, -1, 1, 1) + self.bias.view(1, -1, 1, 1)
        return out
